import React from 'react';
/**
 * @internal
 */
export interface MouseCoordinate {
    x: number;
    y: number;
}
export interface OverlaysProps {
    isInChartBounds: boolean;
    mousePosition?: MouseCoordinate;
}
export interface OverlayHandlers {
    click?: (e: React.MouseEvent) => void;
    move?: (e: React.MouseEvent, newState: OverlaysProps) => void;
    enter?: (e: React.MouseEvent, newState: OverlaysProps) => void;
    leave?: (e: React.MouseEvent, newState: OverlaysProps) => void;
    focus?: (e: React.FocusEvent) => void;
    blur?: (e: React.FocusEvent) => void;
}
export interface Magnifier {
    value: string | number;
    x?: number;
    y?: number;
    backgroundColor?: string;
}
